use nexflow_rust_evaluation::{SchemaEngine, Selection, diagnostic, display_id, evaluate, evaluate_library_case, files::LocalInputs, parse_yaml, safe_locator};
use serde_json::{Value, json};
use std::{fs, path::PathBuf};
fn repository() -> PathBuf { PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../..").canonicalize().unwrap() }
fn schemas() -> SchemaEngine { SchemaEngine::repository(&repository().join("schemas")).unwrap() }
fn selection(path: &str) -> Selection { Selection { root: repository().join(path), project: None, files: None } }
#[test] fn independent_library_validates() { let out = evaluate("validate", &selection("fixtures/cli/valid/minimal-project"), &schemas()); assert_eq!(out["success"], true); assert_eq!(out["result"]["documentCount"], 3); assert_eq!(out["executionAuthorized"], false); assert_eq!(out["checks"]["semantic"], "not-run"); }
#[test] fn declared_inspection() { let out = evaluate("inspect", &selection("fixtures/cli/valid/minimal-project"), &schemas()); assert_eq!(out["result"]["inspection"]["resources"].as_array().unwrap().len(), 4); assert_eq!(out["result"]["inspection"]["references"].as_array().unwrap().len(), 2); assert_eq!(out["result"]["inspection"]["referencesResolved"], false); }
#[test] fn invalid_inputs_suppress_inspection() { for root in ["fixtures/cli/invalid/schema", "fixtures/cli/invalid/yaml-syntax", "fixtures/cli/invalid/hint-escape"] { let out = evaluate("inspect", &selection(root), &schemas()); assert_eq!(out["result"], Value::Null); assert_eq!(out["success"], false); } }
#[test] fn runtime_rejected_without_root_read() { let out = evaluate("run", &selection("missing"), &schemas()); assert_eq!(out["exitCode"], 2); assert_eq!(out["checks"]["discovery"], "not-run"); }
#[test] fn duplicate_keys_fail() { for text in ["a: 1\na: 2\n", "outer:\n  a: 1\n  a: 2\n"] { assert_eq!(parse_yaml(text).unwrap_err(), "duplicate-key"); } }
#[test] fn malformed_and_multiple_documents_fail() { for text in ["a: [", "---\na: 1\n---\nb: 2", ""] { assert!(parse_yaml(text).is_err()); } }
#[test] fn tags_aliases_and_nonfinite_fail() { for text in ["a: !execute value", "a: !!str value", "a: &a [1]\nb: *a", "a: .inf", "a: .nan", "? [a, b]\n: value", "true: value"] { assert!(parse_yaml(text).is_err(), "{text}"); } }
#[test] fn scalar_meaning_is_native() { assert_eq!(parse_yaml("a: true\nb: yes\nc: 2026-10-03\nd: 12\ne: 1.5").unwrap(), json!({"a":true,"b":"yes","c":"2026-10-03","d":12,"e":1.5})); }
#[test] fn depth_and_byte_budgets() { assert!(parse_yaml(&format!("{}0{}", "[".repeat(101), "]".repeat(101))).is_err()); assert!(parse_yaml(&"a".repeat(1024*1024+1)).is_err()); }
#[test] fn selection_bounds_and_traversal() { let mut input = selection("fixtures/cli/valid/minimal-project"); input.files = Some(vec!["../project.yaml".into()]); let out = evaluate("validate", &input, &schemas()); assert!(out.to_string().contains("NF-DISCOVERY-OUTSIDE-ROOT")); input.files = Some(vec!["project.yaml".into();129]); assert_eq!(evaluate("validate", &input, &schemas())["checks"]["discovery"], "failed"); }
#[test] fn ambiguous_and_duplicate_selections() { assert_eq!(evaluate("validate", &selection("fixtures/cli/invalid/multiple-projects"), &schemas())["diagnostics"][0]["code"], "NF-DISCOVERY-MULTIPLE-PROJECTS"); let mut input = selection("fixtures/cli/valid/minimal-project"); input.files = Some(vec!["project.yaml".into(), "project.yaml".into()]); assert!(evaluate("validate", &input, &schemas()).to_string().contains("NF-DISCOVERY-DUPLICATE-SOURCE")); }
#[test] fn fixed_messages_and_redaction() { let text = diagnostic("NF-SCHEMA", Some("../secret"), Some("Project"), Some("/<redacted>"), Some("type")).to_string(); assert!(!text.contains("secret")); assert_eq!(safe_locator("https://invalid/input"), "<redacted-source>"); assert_eq!(display_id(&json!("TOKEN WITH SPACE")), "<redacted-id>"); }
#[test] fn draft2020_local_and_missing_references() { let schema = json!({"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://nexflow.dev/evaluation/test","type":"array","prefixItems":[{"type":"integer"}],"items":false}); assert!(SchemaEngine::validate_local(&[schema.clone()], "https://nexflow.dev/evaluation/test", &json!([1])).is_empty()); let issues = SchemaEngine::validate_local(&[schema], "https://nexflow.dev/evaluation/test", &json!([1,2])); assert_eq!(issues[0]["category"], "items"); assert_eq!(issues[0]["instancePath"], ""); assert_eq!(issues[0]["nativeDiagnostic"]["instancePath"], "/1"); let missing = json!({"$schema":"https://json-schema.org/draft/2020-12/schema","$id":"https://nexflow.dev/evaluation/test","$ref":"https://nexflow.dev/unavailable"}); assert_eq!(SchemaEngine::validate_local(&[missing], "https://nexflow.dev/evaluation/test", &json!(0))[0]["category"], "unresolved-local-schema"); }
#[test] fn unsupported_semantics_never_pass() { for operation in ["semantic-fragment", "workflow-namespace", "artifact-namespace"] { let out = evaluate_library_case(&json!({"id":"case","operation":operation,"input":{}}), &repository(), &schemas()).unwrap(); assert_eq!(out["valid"], Value::Null); assert_eq!(out["status"], "not-implemented"); } }
#[test] fn explicit_root_regular_and_symlink_policy() {
    let directory = std::env::temp_dir().join(format!("nexflow-rust-boundary-{}", std::process::id()));
    fs::create_dir(&directory).unwrap();
    fs::write(directory.join("valid.yaml"), "key: value").unwrap();
    let inputs = LocalInputs::new(&directory).unwrap(); assert_eq!(inputs.read("valid.yaml").unwrap(), "key: value"); assert!(inputs.read("directory.yaml").is_err());
    #[cfg(unix)] { std::os::unix::fs::symlink(directory.join("valid.yaml"), directory.join("link.yaml")).unwrap(); assert!(inputs.read("link.yaml").is_err()); fs::remove_file(directory.join("link.yaml")).unwrap(); }
    fs::remove_file(directory.join("valid.yaml")).unwrap(); fs::remove_dir(&directory).unwrap();
}
